  inline bool sanitize (hb_sanitize_context_t *c,
                        unsigned int *num_entries_out = nullptr) const
  {
    TRACE_SANITIZE (this);
    if (unlikely (!(c->check_struct (this) &&
                    classTable.sanitize (c, this)))) return_trace (false);

    const HBUSHORT *states = (this+stateArrayTable).arrayZ;
    const Entry<Extra> *entries = (this+entryTable).arrayZ;

    unsigned int num_classes = nClasses;
    if (unlikely (hb_unsigned_mul_overflows (num_classes, states[0].static_size)))
      return_trace (false);
    unsigned int row_stride = num_classes * states[0].static_size;

    /* Apple 'kern' table has this peculiarity:
     *
     * "Because the stateTableOffset in the state table header is (strictly
     * speaking) redundant, some 'kern' tables use it to record an initial
     * state where that should not be StartOfText. To determine if this is
     * done, calculate what the stateTableOffset should be. If it's different
     * from the actual stateTableOffset, use it as the initial state."
     *
     * We implement this by calling the initial state zero, but allow *negative*
     * states if the start state indeed was not the first state.  Since the code
     * is shared, this will also apply to 'mort' table.  The 'kerx' / 'morx'
     * tables are not affected since those address states by index, not offset.
     */

    int min_state = 0;
    int max_state = 0;
    unsigned int num_entries = 0;

    int state_pos = 0;
    int state_neg = 0;
    unsigned int entry = 0;
    while (min_state < state_neg || state_pos <= max_state)
    {
      if (min_state < state_neg)
      {
        /* Negative states. */
        if (unlikely (hb_unsigned_mul_overflows (min_state, num_classes)))
          return_trace (false);
        if (unlikely (!c->check_array (&states[min_state * num_classes], -min_state, row_stride)))
          return_trace (false);
        if ((c->max_ops -= state_neg - min_state) < 0)
          return_trace (false);
        { /* Sweep new states. */
          const HBUSHORT *stop = &states[min_state * num_classes];
          if (unlikely (stop > states))
            return_trace (false);
          for (const HBUSHORT *p = states; stop < p; p--)
            num_entries = MAX<unsigned int> (num_entries, *(p - 1) + 1);
          state_neg = min_state;
        }
      }

      if (state_pos <= max_state)
      {
        /* Positive states. */
        if (unlikely (!c->check_array (states, max_state + 1, row_stride)))
          return_trace (false);
        if ((c->max_ops -= max_state - state_pos + 1) < 0)
          return_trace (false);
        { /* Sweep new states. */
          if (unlikely (hb_unsigned_mul_overflows ((max_state + 1), num_classes)))
            return_trace (false);
          const HBUSHORT *stop = &states[(max_state + 1) * num_classes];
          if (unlikely (stop < states))
            return_trace (false);
          for (const HBUSHORT *p = &states[state_pos * num_classes]; p < stop; p++)
            num_entries = MAX<unsigned int> (num_entries, *p + 1);
          state_pos = max_state + 1;
        }
      }

      if (unlikely (!c->check_array (entries, num_entries)))
        return_trace (false);
      if ((c->max_ops -= num_entries - entry) < 0)
        return_trace (false);
      { /* Sweep new entries. */
        const Entry<Extra> *stop = &entries[num_entries];
        for (const Entry<Extra> *p = &entries[entry]; p < stop; p++)
        {
          int newState = new_state (p->newState);
          min_state = MIN (min_state, newState);
          max_state = MAX (max_state, newState);
        }
        entry = num_entries;
      }
    }

    if (num_entries_out)
      *num_entries_out = num_entries;
